def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]

    points = [
        (r, c, grid[r][c])
        for r in range(1, h - 1)
        for c in range(1, w - 1)
        if grid[r][c] != bg
    ]

    def runs(values):
        result = []
        i = 0
        while i < len(values):
            if values[i] == bg:
                i += 1
                continue
            color, start = values[i], i
            while i + 1 < len(values) and values[i + 1] == color:
                i += 1
            result.append((color, start, i))
            i += 1
        return result

    def project(first, second, horizontal):
        # The two lists describe runs on opposing edges. A marker aligned
        # with one run projects to the corresponding position in the other.
        for ca, a0, a1 in first:
            for cb, b0, b1 in second:
                if ca != cb:
                    continue
                for r, c, ink in points:
                    pos = c if horizontal else r

                    if a0 <= pos <= a1:
                        mapped = b0 + pos - a0
                        if mapped > b1:
                            continue
                        source_is_first = True
                    elif b0 <= pos <= b1:
                        mapped = a0 + pos - b0
                        if mapped > a1:
                            continue
                        source_is_first = False
                    else:
                        continue

                    if horizontal:  # top/bottom edges; lines are columns
                        toward_top = source_is_first
                        if toward_top:
                            for rr in range(1, r):
                                out[rr][c] = ink
                        else:
                            for rr in range(r + 1, h - 1):
                                out[rr][c] = ink
                        for rr in range(1, h - 1):
                            out[rr][mapped] = ink
                    else:  # left/right edges; lines are rows
                        toward_left = source_is_first
                        if toward_left:
                            for cc in range(1, c):
                                out[r][cc] = ink
                        else:
                            for cc in range(c + 1, w - 1):
                                out[r][cc] = ink
                        for cc in range(1, w - 1):
                            out[mapped][cc] = ink

    project(runs(grid[0]), runs(grid[-1]), True)
    project(
        runs([grid[r][0] for r in range(h)]),
        runs([grid[r][-1] for r in range(h)]),
        False,
    )

    for r, c, _ in points:
        out[r][c] = 4
    return out
